<script setup>
import { computed, onMounted, onBeforeUnmount, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
const props = defineProps({ api: { type: Function, required: true } });
const rows=ref([]), total=ref(0), page=ref(1), pageSize=ref(20), loading=ref(false), saving=ref(false), dialog=ref(false), teamDialog=ref(false), catalog=ref([]), battle=ref(null), teamDuration=ref(120000), teamPassages=ref([]);
const filters=reactive({q:'',status:'',language:''});
const form=reactive({name:'',language:'zh',schedule:'single',duration:120000,textMinLength:'',passageIds:[]});
const available = computed(()=>catalog.value.filter(x=>x.language===form.language));
const teamAvailable = computed(()=>catalog.value.filter(x=>x.language==='zh'));
const names={draft:'草稿',registration:'检录中',running:'比赛中',paused:'已暂停',finished:'已结束',terminated:'已终止'};
let timer;
async function load(){ loading.value=true;try{const q=new URLSearchParams({...filters,page:String(page.value),pageSize:String(pageSize.value)});const data=await props.api('/api/competitions?'+q);rows.value=data.rows||[];total.value=data.total||0;page.value=data.page||1;}catch(e){ElMessage.error(e.message)}finally{loading.value=false} }
async function loadBattle(){try{battle.value=await props.api('/api/battle/competition/referee')}catch(e){ElMessage.error(e.message)}}
async function loadCatalog(){try{catalog.value=(await props.api('/api/competitions/text-catalog')).rows||[]}catch(e){ElMessage.error(e.message)}}
async function create(){if(!form.name.trim()){ElMessage.warning('请填写赛事名称');return} if(saving.value)return;saving.value=true;try{await props.api('/api/competitions',{method:'POST',body:JSON.stringify({name:form.name.trim(),mode:'speed',schedule:form.schedule,config:{roundMs:form.duration,capacity:60,language:form.language,textMinLength:form.textMinLength||undefined,passageIds:form.passageIds}})});dialog.value=false;form.name='';form.passageIds=[];ElMessage.success('赛事已创建');await load()}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
async function action(item,kind){try{let body; if(kind==='terminate'){await ElMessageBox.confirm(`确定终止「${item.name}」？终止后不可恢复。`,'终止比赛',{type:'warning'});body={reason:'teacher'}} if(kind==='overtime'){const answer=await ElMessageBox.prompt('请输入加时秒数','本轮加时',{inputValue:'30',inputPattern:/^[1-9]\d*$/,inputErrorMessage:'请输入正整数'});body={extraMs:Number(answer.value)*1000}} if(kind==='advance'){const state=await props.api(`/api/competitions/${item.id}/admin`);kind=state.round?.status==='running'?'settle':'start'} if(kind==='start'&&item.schedule==='multi_day'){const answer=await ElMessageBox.prompt('输入计划开始时间，留空立即开始','开始比赛',{inputPlaceholder:'例如 2026-11-20 14:30'});if(answer.value){const plannedAt=Date.parse(answer.value.replace(' ','T'));if(!Number.isFinite(plannedAt)){ElMessage.error('计划时间格式不正确');return}body={plannedAt}}}await props.api(`/api/competitions/${item.id}/${kind}`,{method:'POST',...(body?{body:JSON.stringify(body)}:{})});ElMessage.success('操作成功');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'操作失败')}}
async function decide(item){try{const state=await props.api(`/api/competitions/${item.id}/admin`);if(!state.matches?.length){ElMessage.warning('没有可裁定的场次');return}const m=await ElMessageBox.prompt(state.matches.map((x,i)=>`${i+1}. ${x.sideAName} 对 ${x.sideBName}`).join('；'),'选择场次',{inputValue:String(state.matches.length)});const match=state.matches[Number(m.value)-1];if(!match)return;const sides=[state.sides.find(s=>s.id===match.sideAId),state.sides.find(s=>s.id===match.sideBId)].filter(Boolean);const w=await ElMessageBox.prompt(sides.map((s,i)=>`${i+1}. ${s.name}`).join('；'),'选择胜方',{inputValue:'1'});const winner=sides[Number(w.value)-1];if(!winner)return;const reason=await ElMessageBox.prompt('请输入裁定原因','确认结果',{inputValue:'现场复核后确认'});await props.api(`/api/competitions/${item.id}/result`,{method:'POST',body:JSON.stringify({matchId:match.id,winnerSideId:winner.id,reason:reason.value||''})});ElMessage.success('结果已确认');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'操作失败')}}
async function prepareTeam(){try{if(battle.value?.phase==='waiting'&&battle.value.online>0)await ElMessageBox.confirm('新建房间会清空当前已加入选手，确定继续？','新建比赛房间',{type:'warning'});await props.api('/api/battle/competition/referee/prepare',{method:'POST',body:JSON.stringify({durationMs:teamDuration.value,passageIds:teamPassages.value})});ElMessage.success('房间已准备');await loadBattle()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'操作失败')}}
async function startTeam(){try{await props.api('/api/battle/competition/referee/start',{method:'POST'});ElMessage.success('比赛已开始');await loadBattle()}catch(e){ElMessage.error(e.message)}}
onMounted(()=>{load();loadCatalog();loadBattle();timer=setInterval(()=>{if(teamDialog.value)loadBattle()},5000)});onBeforeUnmount(()=>clearInterval(timer));
</script>
<template>
<div class="page-heading"><div><p class="kicker">赛事主持</p><h1>比赛赛事</h1><p>创建个人赛，管理现场比赛与团队阵营赛。</p></div><div><el-button @click="teamDialog=true;loadBattle()">团队阵营赛</el-button><el-button type="primary" @click="dialog=true">创建个人赛</el-button></div></div>
<section class="report-panel"><div class="filters"><el-input v-model="filters.q" placeholder="搜索赛事名称" clearable class="search-input" @keyup.enter="page=1;load()"/><el-select v-model="filters.status" placeholder="全部状态" clearable @change="page=1;load()"><el-option v-for="(label,key) in names" :key="key" :value="key" :label="label"/></el-select><el-select v-model="filters.language" placeholder="全部语言" clearable @change="page=1;load()"><el-option value="zh" label="中文"/><el-option value="en" label="英文"/></el-select><el-button @click="page=1;load()">查询</el-button></div>
<el-table :data="rows" v-loading="loading" height="100%"><el-table-column prop="name" label="赛事" min-width="180"/><el-table-column label="模式" min-width="130"><template #default="{row}">{{row.mode==='speed'?'个人赛 · '+(row.language==='en'?'英文':'中文'):row.mode==='duel'?'旧版 1v1':'旧版团队赛'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag>{{names[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="检录情况" min-width="150"><template #default="{row}">{{row.readyCount||0}} / {{row.capacity||'—'}} 已准备<br/><small>{{row.playerCount||0}} 人报名 · {{row.onlineCount||0}} 人在线</small></template></el-table-column><el-table-column label="创建时间" min-width="165"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column label="操作" min-width="250"><template #default="{row}"><el-button v-if="row.status==='draft'" link type="primary" @click="action(row,'registration')">开启检录</el-button><el-button v-if="row.status==='registration'" link type="primary" @click="action(row,'start')">开始</el-button><el-button v-if="row.status==='running' && row.mode!=='speed'" link @click="action(row,'advance')">结算 / 下一轮</el-button><el-button v-if="row.status==='running'" link @click="action(row,'pause')">暂停</el-button><el-button v-if="row.status==='running' && row.mode!=='speed'" link @click="action(row,'overtime')">加时</el-button><el-button v-if="row.status==='paused'" link @click="action(row,'resume')">继续</el-button><el-button v-if="['registration','running','paused'].includes(row.status)" link type="danger" @click="action(row,'terminate')">终止</el-button><a v-if="['running','paused','finished'].includes(row.status)" :href="`/board?competition=${row.id}`" target="_blank" rel="noopener">大屏</a> <a v-if="row.status==='finished'" :href="`/api/competitions/${row.id}/export.csv`">导出</a> <el-button v-if="row.status==='finished' && row.mode==='team'" link @click="decide(row)">裁定</el-button></template></el-table-column></el-table><div class="table-footer"><span>共 {{total}} 场</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[10,20,50]" :total="total" layout="sizes,prev,pager,next" @size-change="page=1;load()" @current-change="load"/></div></section>
<el-dialog v-model="dialog" title="创建个人打字赛" width="min(600px,94vw)"><el-form label-position="top" @submit.prevent="create"><el-form-item label="赛事名称"><el-input v-model="form.name" maxlength="40"/></el-form-item><el-form-item label="语言"><el-select v-model="form.language" @change="form.passageIds=[]"><el-option value="zh" label="中文"/><el-option value="en" label="英文"/></el-select></el-form-item><el-form-item label="赛程"><el-select v-model="form.schedule"><el-option value="single" label="单日"/><el-option value="multi_day" label="跨天"/></el-select></el-form-item><el-form-item label="时长"><el-select v-model="form.duration"><el-option v-for="seconds in [60,90,120,180,240,300]" :key="seconds" :value="seconds*1000" :label="seconds+' 秒'"/></el-select></el-form-item><el-form-item label="题面长度"><el-select v-model="form.textMinLength"><el-option label="跟随时长" value=""/><el-option v-for="n in [300,400,600,800]" :key="n" :value="n" :label="'约 '+n+' 字'"/></el-select></el-form-item><el-form-item label="指定文章（可选）"><el-select v-model="form.passageIds" multiple filterable clearable placeholder="留空自动取题"><el-option v-for="p in available" :key="p.id" :label="p.category+' · '+p.title" :value="p.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建</el-button></template></el-dialog>
<el-dialog v-model="teamDialog" title="团队阵营赛控制台" width="min(620px,94vw)"><p>当前状态：{{({waiting:'等待选手',countdown:'开赛倒计时',running:'比赛中',finished:'本局已结束'})[battle?.phase]||'加载中'}} · 在线 {{battle?.online||0}} 人</p><p>红方 {{battle?.teams?.red?.count||0}} 人 · 蓝方 {{battle?.teams?.blue?.count||0}} 人</p><p v-if="battle?.players?.length">{{battle.players.map(p=>p.name+'（'+(p.team==='red'?'红':'蓝')+'）').join('、')}}</p><el-form label-position="top"><el-form-item label="每局时长"><el-select v-model="teamDuration"><el-option v-for="seconds in [60,90,120,180,240]" :key="seconds" :value="seconds*1000" :label="seconds+' 秒'"/></el-select></el-form-item><el-form-item label="指定中文文章（可选）"><el-select v-model="teamPassages" multiple filterable clearable placeholder="留空使用默认短句"><el-option v-for="p in teamAvailable" :key="p.id" :label="p.category+' · '+p.title" :value="p.id"/></el-select></el-form-item></el-form><template #footer><a href="/#battle-competition" target="_blank" rel="noopener">投影战况</a> <el-button :disabled="['countdown','running'].includes(battle?.phase)" @click="prepareTeam">新建比赛房间</el-button><el-button type="primary" :disabled="battle?.phase!=='waiting'||!battle?.teams?.red?.count||!battle?.teams?.blue?.count" @click="startTeam">裁判开始本局</el-button></template></el-dialog>
</template>
